import { useEffect } from "react";

export default function CustomModal({ id, title, fields, onSubmit }) {
    // hàm mở modal từ bên ngoài (cha có thể gọi handleOpen)
    const handleOpen = () => {
        const modal = new window.bootstrap.Modal(document.getElementById(id));
        modal.show();
    };

    // để cha có thể gọi handleOpen
    useEffect(() => {
        if (typeof onSubmit === "function") {
            // không cần return gì, onSubmit sẽ được gọi ở nút submit
        }
    }, [onSubmit]);

    return (
        <>
            <div className="modal fade" id={id} tabIndex="-1" aria-hidden="true">
                <div className="modal-dialog">
                    <div className="modal-content">
                        <div className="modal-header">
                            <h5 className="modal-title">{title}</h5>
                            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Đóng"></button>
                        </div>
                        <div className="modal-body">
                            <form id={`${id}-form`}>
                                {fields.map((field, index) => (
                                    <div className="mb-3" key={index}>
                                        <label className="form-label">{field.label}</label>
                                        {field.type === "select" ? (
                                            <select className="form-select" name={field.name}>
                                                {field.options.map((opt, i) => (
                                                    <option key={i} value={opt.value}>{opt.label}</option>
                                                ))}
                                            </select>
                                        ) : (
                                            <input
                                                type={field.type}
                                                className="form-control"
                                                name={field.name}
                                                defaultValue={field.defaultValue || ""}
                                            />
                                        )}
                                    </div>
                                ))}
                            </form>
                        </div>
                        <div className="modal-footer">
                            <button type="button" className="btn btn-secondary" data-bs-dismiss="modal">
                                Đóng
                            </button>
                            <button
                                type="button"
                                className="btn btn-primary"
                                onClick={() => {
                                    const form = document.getElementById(`${id}-form`);
                                    const formData = new FormData(form);
                                    const data = Object.fromEntries(formData.entries());
                                    onSubmit?.(data); // gọi hàm cha truyền vào
                                }}
                            >
                                Lưu
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
}
